img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  font-size: inherit;
}

input, select, textarea {
  font-family: inherit;
  font-size: inherit;
}

ul, ol {
  list-style: none;
}

/* === TYPOGRAPHY === */
h1, h2, h3, h4, h5, h6 {
  line-height: 1.2;
  font-weight: 700;
  color: var(--color-text);
}

h1 { font-size: var(--font-size-5xl); letter-spacing: -0.02em; }
h2 { font-size: var(--font-size-3xl); letter-spacing: -0.01em; }
h3 { font-size: var(--font-size-xl); }
h4 { font-size: var(--font-size-lg); }

/* === LAYOUT === */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.section {
  padding: var(--space-7) 0;
}

.section--alt {
  background: var(--color-bg);
}

.section--tight {
  padding: var(--space-6) 0;
}

.section-header {
  margin-bottom: var(--space-5);
}

.section-header h2 {
  margin-bottom: var(--space-2);
}

.section-header p {
  color: var(--color-text-secondary);
  font-size: var(--font-size-lg);
}

/* === HEADER / NAV === */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-primary);
  height: var(--header-height);
  box-shadow: var(--shadow-md);
}

.site-header .container {
  display: flex;
  align-items: center;
  height: 100%;
  gap: var(--space-5);
}

.logo {
  font-size: var(--font-size-xl);
  font-weight: 800;
  color: var(--color-white);
  letter-spacing: -0.02em;
  flex-shrink: 0;
  margin-right: var(--space-3);
}

.logo span {
  color: var(--color-highlight);
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  height: 100%;
  flex: 1;
}

.primary-nav a {
  color: rgba(255,255,255,0.85);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  font-weight: 500;
  transition: all var(--transition-fast);
  white-space: nowrap;
  position: relative;
}

.primary-nav a:hover,
.primary-nav a.active {
  color: var(--color-white);
  background: rgba(255,255,255,0.15);
}

.primary-nav a.active {
  background: rgba(255,255,255,0.2);
  font-weight: 600;
}

.primary-nav a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 50%;
  transform: translateX(-50%);
  width: 20px;
  height: 3px;
  background: var(--color-highlight);
  border-radius: var(--radius-full);
}

.mobile-menu-btn {
  display: none;
  color: var(--color-white);
  font-size: var(--font-size-2xl);
  padding: var(--space-2);
  margin-left: auto;
}

/* === HERO === */
.hero {
  padding: var(--space-7) 0 var(--space-6);
  background: linear-gradient(135deg, var(--color-primary) 0%, #0A2472 100%);
  color: var(--color-white);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255,183,0,0.08) 0%, transparent 70%);
  pointer-events: none;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -15%;
  width: 500px;
  height: 500px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(0,108,228,0.1) 0%, transparent 70%);
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  text-align: center;
  margin-bottom: var(--space-5);
}

.hero-content h1 {
  color: var(--color-white);
  font-size: var(--font-size-5xl);
  margin-bottom: var(--space-3);
}

.hero-content p {
  color: rgba(255,255,255,0.8);
  font-size: var(--font-size-xl);
  max-width: 600px;
  margin: 0 auto;
}

/* === SEARCH FORM === */
.search-form {
  position: relative;
  z-index: 2;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: var(--space-4);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: flex-end;
  gap: var(--space-3);
  flex-wrap: wrap;
  max-width: 1000px;
  margin: 0 auto;
}

.search-field {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  flex: 1;
  min-width: 160px;
}

.search-field label {
  font-size: var(--font-size-xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-secondary);
}

.search-field input,
.search-field select {
  padding: var(--space-2) var(--space-3);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  font-size: var(--font-size-sm);
  color: var(--color-text);
  background: var(--color-white);
  transition: border-color var(--transition-fast);
  height: 42px;
}

.search-field input:focus,
.search-field select:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(0,108,228,0.1);
}

.search-field input::placeholder {
  color: var(--color-text-tertiary);
}

.btn-search {
  height: 42px;
  padding: 0 var(--space-5);
  background: var(--color-accent);
  color: var(--color-white);
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: var(--font-size-base);
  transition: background var(--transition-fast);
  white-space: nowrap;
  align-self: flex-end;
}

.btn-search:hover {
  background: var(--color-accent-hover);
}

.checkbox-row {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-top: var(--space-3);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  flex-wrap: wrap;
}

.checkbox-row label {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  cursor: pointer;
  user-select: none;
}

.checkbox-row input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--color-accent);
  cursor: pointer;
}

/* Package type radios */
.package-type-selector {
  display: flex;
  gap: var(--space-2);
  flex-wrap: wrap;
  margin-bottom: var(--space-4);
  justify-content: center;
}

.package-type-option {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: rgba(255,255,255,0.12);
  border: 1.5px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-full);
  color: var(--color-white);
  font-size: var(--font-size-sm);
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.package-type-option:hover {
  background: rgba(255,255,255,0.2);
}

.package-type-option.active {
  background: var(--color-highlight);
  border-color: var(--color-highlight);
  color: var(--color-text);
}

.package-type-option input {
  display: none;
}

/* === TRUST BADGES === */
.trust-badges {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
}

.trust-badge {
  display: flex;
  gap: var(--space-3);
  padding: var(--space-3);
  border-radius: var(--radius-md);
  background: var(--color-bg);
  transition: box-shadow var(--transition-fast);
}

.trust-badge:hover {
  box-shadow: var(--shadow-sm);
}

.trust-badge-icon {
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  background: var(--color-primary-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-xl);
  color: var(--color-primary);
}

.trust-badge-content h4 {
  font-size: var(--font-size-sm);
  font-weight: 600;
  margin-bottom: var(--space-1);
  color: var(--color-text);
}

.trust-badge-content p {
  font-size: var(--font-size-xs);
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* === OFFER CARDS === */
.offers-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
}

.offer-card {
  display: flex;
  gap: var(--space-4);
  padding: var(--space-5);
  border-radius: var(--radius-lg);
  background: var(--color-bg);
  transition: box-shadow var(--transition-fast);
}

.offer-card:hover {
  box-shadow: var(--shadow-md);
}

.offer-card-icon {
  width: 56px;
  height: 56px;
  flex-shrink: 0;
  background: var(--color-highlight);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-2xl);
}

.offer-card-content h3 {
  font-size: var(--font-size-lg);
  margin-bottom: var(--space-2);
}

.offer-card-content p {
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
  margin-bottom: var(--space-3);
  line-height: 1.5;
}

.btn-outline {
  display: inline-block;
  padding: var(--space-2) var(--space-4);
  border: 1.5px solid var(--color-accent);
  color: var(--color-accent);
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: var(--font-size-sm);
  transition: all var(--transition-fast);
}

.btn-outline:hover {
  background: var(--color-accent);
  color: var(--color-white);
}

.btn-primary {
  display: inline-block;
  padding: var(--space-2) var(--space-4);
  background: var(--color-accent);
  color: var(--color-white);
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: var(--font-size-sm);
  transition: background var(--transition-fast);
}

.btn-primary:hover {
  background: var(--color-accent-hover);
}

/* === PROPERTY TYPES === */
.property-types {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  justify-content: center;
}

.property-type-tag {
  padding: var(--space-2) var(--space-3);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.property-type-tag:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
  background: var(--color-primary-light);
}

/* === TABS === */
.tabs-nav {
  display: flex;
  gap: var(--space-1);
  overflow-x: auto;
  padding-bottom: var(--space-3);
  margin-bottom: var(--space-4);
  scrollbar-width: none;
  -ms-overflow-style: none;
  border-bottom: 2px solid var(--color-border-light);
}

.tabs-nav::-webkit-scrollbar {
  display: none;
}

.tab-btn {
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text-secondary);
  white-space: nowrap;
  transition: all var(--transition-fast);
  border: 1.5px solid transparent;
}

.tab-btn:hover {
  color: var(--color-primary);
  background: var(--color-primary-light);
}

.tab-btn.active {
  background: var(--color-primary);
  color: var(--color-white);
  font-weight: 600;
}

.tab-panel {
  display: none;
}

.tab-panel.active {
  display: block;
}

/* === DESTINATION CARDS (trip planner) === */
.destination-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-3);
}

.destination-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: box-shadow var(--transition-fast);
  cursor: pointer;
}

.destination-card:hover {
  box-shadow: var(--shadow-md);
}

.destination-card-img {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, var(--color-primary-light), var(--color-bg-alt));
  position: relative;
}

.destination-card-img::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.3), transparent);
}

.destination-card-body {
  padding: var(--space-3);
}

.destination-card-body h4 {
  font-size: var(--font-size-base);
  margin-bottom: var(--space-1);
}

.destination-card-body p {
  font-size: var(--font-size-xs);
  color: var(--color-text-tertiary);
}

/* === PROPERTY CARDS (carousel) === */
.carousel-wrapper {
  position: relative;
}

.carousel {
  display: flex;
  gap: var(--space-4);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: var(--space-2);
}

.carousel::-webkit-scrollbar {
  display: none;
}

.property-card {
  flex: 0 0 300px;
  scroll-snap-align: start;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--color-border-light);
  transition: box-shadow var(--transition-fast);
}

.property-card:hover {
  box-shadow: var(--shadow-md);
}

.property-card-img {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #D4E0F0, #B8CCE8);
  position: relative;
}

.property-card-body {
  padding: var(--space-3);
}

.property-card-body h3 {
  font-size: var(--font-size-base);
  margin-bottom: var(--space-1);
  line-height: 1.3;
}

.property-card-body .location {
  font-size: var(--font-size-xs);
  color: var(--color-text-tertiary);
  margin-bottom: var(--space-2);
}

.property-card-body .meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  margin-bottom: var(--space-2);
}

.property-card-body .rating {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.property-card-body .rating-score {
  background: var(--color-rating);
  color: var(--color-white);
  font-weight: 700;
  font-size: var(--font-size-xs);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
}

.property-card-body .rating-text {
  font-size: var(--font-size-xs);
  color: var(--color-text-secondary);
}

.property-card-body .reviews {
  font-size: var(--font-size-xs);
  color: var(--color-text-tertiary);
}

.property-card-body .price {
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--color-text);
}

.property-card-body .price-original {
  font-size: var(--font-size-sm);
  color: var(--color-error);
  text-decoration: line-through;
  margin-left: var(--space-2);
}

.property-card-body .deal-badge {
  display: inline-block;
  padding: 2px 8px;
  background: #FFF3CD;
  color: #856404;
  font-size: var(--font-size-xs);
  font-weight: 600;
  border-radius: var(--radius-full);
  margin-bottom: var(--space-2);
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-xl);
  color: var(--color-text);
  box-shadow: var(--shadow-md);
  z-index: 10;
  transition: all var(--transition-fast);
}

.carousel-arrow:hover {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.carousel-arrow--left { left: -16px; }
.carousel-arrow--right { right: -16px; }
.carousel-arrow:disabled {
  opacity: 0;
  pointer-events: none;
}

/* === TRENDING DESTINATIONS === */
.trending-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  justify-content: center;
}

.trending-item {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: var(--color-bg);
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: var(--font-size-sm);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.trending-item:hover {
  background: var(--color-primary);
  color: var(--color-white);
  transform: translateY(-2px);
}

.trending-item-flag {
  font-size: var(--font-size-lg);
}

/* === EXPLORE DESTINATIONS GRID === */
.explore-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-3);
}

.explore-card {
  text-align: center;
  padding: var(--space-4) var(--space-3);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  cursor: pointer;
  border: 1px solid var(--color-border-light);
}

.explore-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-primary);
  transform: translateY(-2px);
}

.explore-card-img {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  margin: 0 auto var(--space-3);
  background: linear-gradient(135deg, var(--color-primary-light), var(--color-bg-alt));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-2xl);
}

.explore-card h4 {
  font-size: var(--font-size-sm);
  margin-bottom: var(--space-1);
}

.explore-card p {
  font-size: var(--font-size-xs);
  color: var(--color-text-tertiary);
}

/* === WEEKEND DEALS === */
.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-4);
}

.deal-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--color-border-light);
  transition: box-shadow var(--transition-fast);
}

.deal-card:hover {
  box-shadow: var(--shadow-md);
}

.deal-card-img {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #E0D4CC, #CCC0B8);
  position: relative;
}

.deal-card-img .savings-badge {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  padding: 4px 12px;
  background: var(--color-highlight);
  color: var(--color-text);
  font-size: var(--font-size-xs);
  font-weight: 700;
  border-radius: var(--radius-full);
}

.deal-card-body {
  padding: var(--space-3);
}

.deal-card-body h3 {
  font-size: var(--font-size-base);
  margin-bottom: var(--space-1);
}

.deal-card-body .location {
  font-size: var(--font-size-xs);
  color: var(--color-text-tertiary);
  margin-bottom: var(--space-2);
}

.deal-card-body .meta {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--font-size-xs);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-3);
}

.deal-card-body .meta .divider {
  color: var(--color-border);
}

.deal-card-body .price-row {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
}

.deal-card-body .price-original {
  font-size: var(--font-size-sm);
  color: var(--color-text-tertiary);
  text-decoration: line-through;
}

.deal-card-body .price-sale {
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--color-text);
}

.deal-card-body .nights {
  font-size: var(--font-size-xs);
  color: var(--color-text-tertiary);
}

/* === HOMES GUESTS LOVE === */
.homes-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.home-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--color-border-light);
  transition: box-shadow var(--transition-fast);
}

.home-card:hover {
  box-shadow: var(--shadow-md);
}

.home-card-img {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #D4E8D4, #B8D4B8);
}

.home-card-body {
  padding: var(--space-3);
}

.home-card-body h3 {
  font-size: var(--font-size-base);
  margin-bottom: var(--space-1);
}

.home-card-body .location {
  font-size: var(--font-size-xs);
  color: var(--color-text-tertiary);
  margin-bottom: var(--space-2);
}

.home-card-body .meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* === LOYALTY CTA === */
.loyalty-cta {
  background: linear-gradient(135deg, var(--color-primary), #0A2472);
  color: var(--color-white);
  text-align: center;
  padding: var(--space-7) 0;
  border-radius: var(--radius-xl);
  position: relative;
  overflow: hidden;
}

.loyalty-cta::before {
  content: '';
  position: absolute;
  top: -40%;
  right: -10%;
  width: 400px;
  height: 400px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255,183,0,0.1), transparent);
  pointer-events: none;
}

.loyalty-cta h2 {
  color: var(--color-white);
  font-size: var(--font-size-4xl);
  margin-bottom: var(--space-2);
}

.loyalty-cta .sub-headline {
  color: var(--color-highlight);
  font-size: var(--font-size-lg);
  font-weight: 600;
  margin-bottom: var(--space-3);
}

.loyalty-cta p {
  color: rgba(255,255,255,0.8);
  max-width: 500px;
  margin: 0 auto var(--space-4);
}

.loyalty-cta-buttons {
  display: flex;
  gap: var(--space-3);
  justify-content: center;
  flex-wrap: wrap;
}

.loyalty-cta .btn-primary {
  background: var(--color-highlight);
  color: var(--color-text);
  padding: var(--space-3) var(--space-6);
  border-radius: var(--radius-sm);
  font-size: var(--font-size-base);
  font-weight: 700;
}

.loyalty-cta .btn-primary:hover {
  background: var(--color-highlight-hover);
}

.loyalty-cta .btn-outline-white {
  display: inline-block;
  padding: var(--space-3) var(--space-6);
  border: 2px solid var(--color-white);
  color: var(--color-white);
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: var(--font-size-base);
  transition: all var(--transition-fast);
}

.loyalty-cta .btn-outline-white:hover {
  background: var(--color-white);
  color: var(--color-primary);
}

/* === POPULAR LINKS === */
.popular-links-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-2) var(--space-4);
}

.popular-links-list a {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  padding: var(--space-1) 0;
  transition: color var(--transition-fast);
  line-height: 1.8;
}

.popular-links-list a:hover {
  color: var(--color-primary-hover);
  text-decoration: underline;
}

/* === PACKAGE BENEFITS === */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.benefit-card {
  text-align: center;
  padding: var(--space-5);
  border-radius: var(--radius-lg);
  background: var(--color-bg);
  transition: box-shadow var(--transition-fast);
}

.benefit-card:hover {
  box-shadow: var(--shadow-sm);
}

.benefit-card-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto var(--space-3);
  background: var(--color-primary-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-2xl);
}

.benefit-card h3 {
  font-size: var(--font-size-base);
  margin-bottom: var(--space-2);
}

.benefit-card p {
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
  line-height: 1.5;
}

/* === PACKAGE DESTINATIONS === */
.package-dest-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

.package-dest-card {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-light);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.package-dest-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-primary);
  transform: translateY(-2px);
}

.package-dest-card-img {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--color-primary-light), var(--color-bg-alt));
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-xl);
}

.package-dest-card-body h4 {
  font-size: var(--font-size-base);
  margin-bottom: var(--space-1);
}

.package-dest-card-body p {
  font-size: var(--font-size-xs);
  color: var(--color-text-tertiary);
}

/* === RENTAL COMPANIES === */
.companies-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: var(--space-3);
}

.company-card {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4);
  border-radius: var(--radius-md);
  background: var(--color-bg);
  font-weight: 700;
  font-size: var(--font-size-lg);
  color: var(--color-text-tertiary);
  border: 1px solid var(--color-border-light);
  transition: all var(--transition-fast);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  min-height: 72px;
}

.company-card:hover {
  box-shadow: var(--shadow-sm);
  color: var(--color-primary);
  border-color: var(--color-primary);
}

/* === CREDIT CARD PROMO === */
.credit-promo {
  display: flex;
  align-items: center;
  gap: var(--space-5);
  padding: var(--space-5);
  background: linear-gradient(135deg, #FFF8E1, #FFECB3);
  border-radius: var(--radius-lg);
  border: 1px solid rgba(255,183,0,0.3);
}

.credit-promo-icon {
  width: 72px;
  height: 72px;
  flex-shrink: 0;
  background: var(--color-highlight);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-2xl);
}

.credit-promo-content {
  flex: 1;
}

.credit-promo-content h3 {
  font-size: var(--font-size-lg);
  margin-bottom: var(--space-2);
}

.credit-promo-content p {
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
  margin-bottom: var(--space-3);
}

/* === FAQ ACCORDION === */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--color-border-light);
}

.faq-question {
  width: 100%;
  text-align: left;
  padding: var(--space-4) var(--space-2);
  font-size: var(--font-size-base);
  font-weight: 600;
  color: var(--color-text);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-3);
  transition: color var(--transition-fast);
}

.faq-question:hover {
  color: var(--color-accent);
}

.faq-question .faq-icon {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-lg);
  transition: all var(--transition-base);
}

.faq-item.open .faq-icon {
  background: var(--color-primary);
  color: var(--color-white);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}

.faq-item.open .faq-answer {
  max-height: 200px;
  padding: 0 var(--space-2) var(--space-4);
}

.faq-answer p {
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
  line-height: 1.6;
}

/* === RENTAL DESTINATIONS TABLE === */
.destinations-table {
  width: 100%;
  border-collapse: collapse;
}

.destinations-table th {
  text-align: left;
  padding: var(--space-3);
  font-size: var(--font-size-xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-tertiary);
  border-bottom: 2px solid var(--color-border);
}

.destinations-table td {
  padding: var(--space-3);
  font-size: var(--font-size-sm);
  border-bottom: 1px solid var(--color-border-light);
}

.destinations-table tr:hover td {
  background: var(--color-bg);
}

.destinations-table .price-cell {
  font-weight: 700;
  color: var(--color-text);
}

/* === RECOMMENDED ATTRACTIONS === */
.attractions-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-4);
}

.attraction-card {
  display: flex;
  gap: var(--space-3);
  padding: var(--space-3);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-light);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.attraction-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-primary);
  transform: translateY(-2px);
}

.attraction-card-img {
  width: 80px;
  height: 80px;
  flex-shrink: 0;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, #D4E0F0, #B8CCE8);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-xl);
}

.attraction-card-body h4 {
  font-size: var(--font-size-sm);
  margin-bottom: var(--space-1);
  line-height: 1.4;
}

.attraction-card-body p {
  font-size: var(--font-size-xs);
  color: var(--color-text-tertiary);
}

/* === NEARBY DESTINATIONS === */
.nearby-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: var(--space-3);
}

.nearby-card {
  text-align: center;
  padding: var(--space-4);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-light);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.nearby-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.nearby-card-img {
  width: 72px;
  height: 72px;
  margin: 0 auto var(--space-3);
  border-radius: 50%;
  background: linear-gradient(135deg, var(--color-primary-light), var(--color-bg-alt));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-xl);
}

.nearby-card h4 {
  font-size: var(--font-size-sm);
  margin-bottom: var(--space-1);
}

.nearby-card p {
  font-size: var(--font-size-xs);
  color: var(--color-text-tertiary);
}

/* === ACCOUNT CTA === */
.account-cta {
  text-align: center;
  padding: var(--space-7) 0;
  background: var(--color-bg);
  border-radius: var(--radius-xl);
}

.account-cta h2 {
  font-size: var(--font-size-3xl);
  margin-bottom: var(--space-2);
}

.account-cta .sub-headline {
  color: var(--color-primary);
  font-size: var(--font-size-lg);
  font-weight: 600;
  margin-bottom: var(--space-3);
}

.account-cta p {
  color: var(--color-text-secondary);
  max-width: 500px;
  margin: 0 auto var(--space-4);
}

/* === FOOTER === */
.site-footer {
  background: var(--color-primary);
  color: var(--color-white);
  padding: var(--space-7) 0 var(--space-5);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-5);
  margin-bottom: var(--space-6);
}

.footer-col h4 {
  color: var(--color-white);
  font-size: var(--font-size-sm);
  margin-bottom: var(--space-3);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.footer-col a {
  color: rgba(255,255,255,0.7);
  font-size: var(--font-size-sm);
  transition: color var(--transition-fast);
  line-height: 1.5;
}

.footer-col a:hover {
  color: var(--color-highlight);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.15);
  padding-top: var(--space-4);
  font-size: var(--font-size-xs);
  color: rgba(255,255,255,0.5);
  text-align: center;
  line-height: 1.6;
}

/* === RESPONSIVE === */
@media (max-width: 1024px) {
  h1 { font-size: var(--font-size-4xl); }
  h2 { font-size: var(--font-size-2xl); }

  .trust-badges { grid-template-columns: repeat(2, 1fr); }
  .offers-grid { grid-template-columns: 1fr; }
  .explore-grid { grid-template-columns: repeat(3, 1fr); }
  .homes-grid { grid-template-columns: repeat(2, 1fr); }
  .package-dest-grid { grid-template-columns: repeat(2, 1fr); }
  .nearby-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .benefits-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  :root {
    --header-height: 56px;
    --font-size-5xl: 2rem;
    --font-size-4xl: 1.75rem;
    --font-size-3xl: 1.5rem;
    --font-size-2xl: 1.25rem;
  }

  .section { padding: var(--space-6) 0; }
  .container { padding: 0 var(--space-3); }

  .mobile-menu-btn { display: block; }

  .primary-nav {
    display: none;
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--color-primary);
    flex-direction: column;
    padding: var(--space-3);
    gap: var(--space-1);
    box-shadow: var(--shadow-lg);
    height: auto;
  }

  .primary-nav.open { display: flex; }

  .primary-nav a {
    width: 100%;
    padding: var(--space-3);
    border-radius: var(--radius-md);
  }

  .primary-nav a.active::after { display: none; }

  .hero-content h1 { font-size: var(--font-size-3xl); }
  .hero-content p { font-size: var(--font-size-base); }

  .search-form {
    flex-direction: column;
    gap: var(--space-2);
  }

  .search-field { min-width: 100%; }

  .trust-badges { grid-template-columns: 1fr; }
  .explore-grid { grid-template-columns: repeat(2, 1fr); }
  .homes-grid { grid-template-columns: 1fr; }
  .popular-links-list { grid-template-columns: repeat(2, 1fr); }
  .package-dest-grid { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .nearby-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .credit-promo { flex-direction: column; text-align: center; }
  .deal-card-body .price-row { flex-wrap: wrap; }
  .destination-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }

  .property-card { flex: 0 0 260px; }

  .carousel-arrow--left { left: -8px; }
  .carousel-arrow--right { right: -8px; }
  .carousel-arrow { width: 36px; height: 36px; font-size: var(--font-size-base); }
}

@media (max-width: 480px) {
  .explore-grid { grid-template-columns: 1fr; }
  .popular-links-list { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .nearby-grid { grid-template-columns: 1fr; }
  .destination-grid { grid-template-columns: 1fr; }
  .companies-grid { grid-template-columns: repeat(2, 1fr); }
  .tabs-nav { gap: 0; }
  .tab-btn { padding: var(--space-2) var(--space-3); font-size: var(--font-size-xs); }
}

/* === ANIMATIONS === */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
  html { scroll-behavior: auto; }
}

/* === FOCUS === */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* === UTILITY === */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}
